labs.solution:
"""drive_report.py - storage report for the robotics club's shared drive.

A folder is a dictionary. Each key is a name; each value is either a file
size in KB (an int) or another folder (a dictionary).
"""

DRIVE = {
    "budget.xlsx": 48,
    "minutes": {"jan.docx": 22, "feb.docx": 19},
    "media": {
        "logo.png": 310,
        "events": {"fair.jpg": 2400, "gala.jpg": 3100, "fair_map.pdf": 640},
    },
    "readme.txt": 3,
}


def is_folder(item):
    """Return True if item is a folder (a dictionary), False if it is a file size."""
    return isinstance(item, dict)


def count_files(folder):
    """Return the number of files in folder and all its subfolders."""
    count = 0
    for name in folder:
        if is_folder(folder[name]):
            count += count_files(folder[name])
        else:
            count += 1
    return count


def total_kb(folder):
    """Return the total size in KB of folder and all its subfolders."""
    total = 0
    for name in folder:
        item = folder[name]
        if is_folder(item):
            total += total_kb(item)
        else:
            total += item
    return total


def find_files(target, folder, path=""):
    """Return the paths of the files whose names contain target, in folder
    and all its subfolders. path is the folder's own path, such as "media/"."""
    files = []
    for name in folder:
        item = folder[name]
        if is_folder(item):
            files.extend(find_files(target, item, path + name + "/"))
        elif target in name:
            files.append(path + name)
    return files


def main():
    """Print the drive's file count, total size and the files matching a search."""
    target = input("Search for? ")
    print("Files:", count_files(DRIVE))
    print("Total:", total_kb(DRIVE), "KB")
    matches = find_files(target, DRIVE)
    if not matches:
        print("No matches")
    for path in matches:
        print(path)


if __name__ == "__main__":
    main()

"""steps.py - weekly report from a fitness watch export."""

KM_PER_STEP = 0.0008
GOAL = 8000


def parse_steps(line):
    """Convert a line such as "8200, 10450, -1" into a list of ints."""
    return list(map(int, line.split(",")))


def worn(steps):
    """Predicate: True if the watch was worn that day. The watch writes -1
    for a day it wasn't worn; 0 is a real (very lazy) day."""
    return steps >= 0


def worn_days(days):
    """Return a list of the step counts for the days the watch was worn."""
    return list(filter(worn, days))


def km_report(days):
    """Return a line such as "6.6 km | 8.4 km" for the given step counts."""
    def to_km(steps):
        return "%.1f km" % (steps * KM_PER_STEP)
    return " | ".join(map(to_km, days))


def met_goal(steps):
    """Predicate: True if the day reached at least GOAL steps."""
    return steps >= GOAL


def goal_days(days):
    """Return how many days reached at least GOAL steps."""
    return len(list(filter(met_goal, days)))


def main():
    """Read one week of steps and print the report."""
    line = input("This week's steps? ")
    days = worn_days(parse_steps(line))
    print("Days worn:", len(days))
    print("Distance:", km_report(days))
    print("Goal met on", goal_days(days), "days")


if __name__ == "__main__":
    main()

